#include <iostream>
#include <vector>
using namespace std;

void lcsLength(string &s1, string &s2, vector<vector<int>> &dp) {
    int m = s1.size(), n = s2.size();
    for (int i = m - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            if (s1[i] == s2[j])
                dp[i][j] = dp[i + 1][j + 1] + 1;
            else
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1]);
        }
    }
}

void backtrack(string &s1, string &s2, int i, int j, int lcsLen,
               vector<vector<int>> &dp, string &cur, vector<string> &res) {
    if (cur.size() == lcsLen) {
        res.push_back(cur);
        return;
    }

    if (i == (int)s1.size() || j == (int)s2.size())
        return;

    int built = cur.size();

    for (char ch = 'a'; ch <= 'z'; ++ch) {
        bool found = false;

        for (int ii = i; ii < (int)s1.size(); ++ii) {
            if (s1[ii] != ch) continue;

            for (int jj = j; jj < (int)s2.size(); ++jj) {
                if (s2[jj] == ch && dp[ii][jj] == lcsLen - built) {
                    cur.push_back(ch);
                    backtrack(s1, s2, ii + 1, jj + 1, lcsLen, dp, cur, res);
                    cur.pop_back();
                    found = true;
                    break;
                }
            }

            if (found) break;
        }
    }
}

vector<string> allLCS(string &s1, string &s2) {
    int n = s1.size(), m = s2.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1));

    lcsLength(s1, s2, dp);

    int lcsLen = dp[0][0];

    vector<string> res;
    string cur;
    backtrack(s1, s2, 0, 0, lcsLen, dp, cur, res);

    return res;
}

int main() {
    string s1 = "abac";
    string s2 = "aabca";

    vector<string> res = allLCS(s1, s2);

    cout << "[";
    for (int i = 0; i < res.size(); ++i) {
        cout << "\"" << res[i] << "\"";
        if (i + 1 < res.size()) cout << ", ";
    }
    cout << "]\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <set>
using namespace std;

bool isSubseq(string &t, string &s) {
    int i = 0, j = 0;

    while (i < t.size() && j < s.size()) {
        if (t[i] == s[j])
            ++i;
        ++j;
    }

    return i == t.size();
}

vector<string> allLCS(string &s1, string &s2) {
    int n = s1.size();
    int best = 0;
    set<string> st;

    for (int mask = 0; mask < (1 << n); ++mask) {
        string sub;

        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i))
                sub.push_back(s1[i]);
        }

        int len = sub.size();

        if (len < best)
            continue;

        if (isSubseq(sub, s2)) {
            if (len > best) {
                best = len;
                st.clear();
            }
            st.insert(sub);
        }
    }

    vector<string> ans;

    for (auto i : st)
        ans.push_back(i);

    return ans;
}

int main() {
    string s1 = "abac";
    string s2 = "aabca";

    auto res = allLCS(s1, s2);

    cout << "[";
    for (int i = 0; i < res.size(); ++i) {
        cout << "\"" << res[i] << "\"";
        if (i + 1 < res.size())
            cout << ", ";
    }
    cout << "]\n";

    return 0;
}

