bool hasIncreasingDigits(int num, int n)
{
    string s = to_string(num);

    if (s.length() != n)
        return false;

    for (int i = 1; i < n; i++)
    {
        if (s[i] <= s[i - 1])
            return false;
    }

    return true;
}

