    if (n > 9)
        return result;

    int start = (n == 1) ? 0 : pow(10, n - 1);
    int end = pow(10, n) - 1;

    for (int num = start; num <= end; num++)
    {
        if (hasIncreasingDigits(num, n))
            result.push_back(num);
    }

    return result;
}

