{
    if (n == 0)
        return 0;

    return a[n - 1] + sum(a, n - 1);
}

int main()
{
    int n;
    cin >> n;

    vector<long long> a(n);
    for (int i = 0; i < n; i++)
        cin >> a[i];

    double average = sum(a, n) / n;

    cout << fixed << setprecision(6) << average << endl;
    return 0;
}

