long long combination(int n, int r)
{
    if (r == 0 || r == n)
        return 1;

    return combination(n - 1, r - 1) + combination(n - 1, r);
}

int main()
{
    int n, r;
    cin >> n >> r;

    if (r > n)
        cout << 0 << endl;
    else
        cout << combination(n, r) << endl;

    return 0;
}

