using namespace std;

int main()
{
    int n;
    long long x;
    cin >> n >> x;

    vector<long long> a(n);
    for (int i = 0; i < n; i++)
        cin >> a[i];

    vector<long long> sums;
    sums.push_back(a[0]);

    for (int i = 1; i < n; i++)
    {
        vector<long long> next;
        for (long long sum : sums)
        {
            next.push_back(sum + a[i]);
            next.push_back(sum - a[i]);
        }
        sums = next;
    }

    bool found = false;
    for (long long sum : sums)
    {
        if (sum == x)
        {
            found = true;
            break;
        }
    }

    cout << (found ? "YES" : "NO") << endl;
    return 0;
}

