bool canReach(long long n)
{
    if (n == 1)
        return true;

    if (n % 10 != 0)
        return false;

    return canReach(n / 10) || (n % 20 == 0 && canReach(n / 20));
}

int main()
{
    int t;
    cin >> t;

    while (t--)
    {
        long long n;
        cin >> n;

        cout << (canReach(n) ? "YES" : "NO") << endl;
    }

    return 0;
}

