int main()
{
    int s, e;
    cin >> s >> e;

    long long dp[16] = {};
    dp[s] = 1;

    for (int i = s + 1; i <= e; i++)
    {
        dp[i] = dp[i - 1];

        if (i - 2 >= s)
            dp[i] += dp[i - 2];

        if (i - 3 >= s)
            dp[i] += dp[i - 3];
    }

    cout << dp[e] << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void leftMax(const vector<long long>& a, vector<long long>& result, int index)
{
    if (index == a.size())
        return;

    if (index == 0)
        result[index] = a[index];
    else
        result[index] = max(result[index - 1], a[index]);

    leftMax(a, result, index + 1);
}

int main()
{
    int n;
    cin >> n;

    vector<long long> a(n), result(n);

    for (int i = 0; i < n; i++)
        cin >> a[i];

    leftMax(a, result, 0);

    for (int i = 0; i < n; i++)
        cout << result[i] << " ";

    cout << endl;
    return 0;
}

